//! `func` generated by `mlirformat tblgen` (`func.gen.rs`) against the `mlir-opt` 22.1.8 fixtures.
//! One test crate per dialect so cargo builds them in parallel; `cargo test --features gen-tests`.

#[path = "../common/mod.rs"]
mod common;
#[path = "func.gen.rs"]
mod func;

#[test]
fn func_matches_mlir_opt() {
    let mut opt = mlirformat::MlirOpt::new();
    opt.load(func::FuncDialect);
    common::Fixtures::check_dialect(&opt, "func");
}
